insert into public.categories (slug, name, name_so, tagline, tagline_so, description, description_so, cover_image, sort_order) values
  ('herbal', 'Herbal Products', 'Alaabooyinka Dhireed', 'Botanicals, natural ingredients & herbal oils', 'Dhir, walxo dabiici ah & saliidaha dhireed', 'Traditional herbs, pure natural ingredients and nourishing herbal oils, carefully sourced for everyday balance.', 'Dhir dhaqameed, walxo dabiici ah oo saafi ah iyo saliido dhireed oo nafaqeeya, si taxaddar leh loo soo xulay si loo helo dheelitir maalinle ah.', 'saliida-mucjisada.webp', 0),
  ('supplements', 'Dietary Supplements', 'Kaabayaasha Nafaqada', 'Everyday supplements & essential minerals', 'Kaabayaal maalinle ah & macdano muhiim ah', 'Everyday dietary supplements — from zinc, iron, omega-3 and collagen to probiotics, amino acids and herbal extracts.', 'Kaabayaal nafaqo oo maalinle ah — laga bilaabo zinc, bir, omega-3 iyo kolajin ilaa probiotics, amino acids iyo soosaarka dhirta.', 'ashwagandha.webp', 1),
  ('sports', 'Sports Nutrition', 'Nafaqada Isboortiga', 'Creatine, protein & performance', 'Creatine, borotiin & waxqabad', 'Clean, effective nutrition for athletes, gym-goers and active people — creatine, protein, gainers and pre-workouts.', 'Nafaqo nadiif ah oo waxtar leh oo loogu talagalay ciyaartoyda, dadka jimicsiga iyo dadka firfircoon — creatine, borotiin, miisaan-kordhiyeyaal iyo pre-workout.', 'c4-original.webp', 2),
  ('vitamins', 'Vitamins', 'Fitamiinno', 'Everyday vitamins for vitality', 'Fitamiinno maalinle ah oo firfircooni leh', 'High-quality vitamins to support immunity, energy and long-term health.', 'Fitamiinno tayo sare leh oo loogu talagalay taageeridda difaaca jirka, tamarta iyo caafimaadka muddada dheer.', 'c1000.webp', 3)
insert into public.products (slug, name, name_so, brand, aliases, category_id, subcategory, facts, description, description_so, benefits, supplied_benefits, caution, image_labels, price, images, in_stock, is_featured, sort_order) values
  ('chillflex-herbal-cream-mint', 'ChillFlex Herbal Cream with Mint', null, 'ChillFlex', '{}'::text[], (select id from public.categories where slug = 'herbal'), 'general', '98 g · herbal joint & muscle cream', 'A herbal joint and muscle cream with mint that gives an instant cooling sensation — made for massage after exercise or a long day.', 'Kareem dhireed oo loogu talagalay kalagoysyada iyo murqaha, kana kooban reexaan (mint), kaas oo isla markiiba siiya dareen qabow — loogu talagalay duugis kadib jimicsi ama maalin dheer.', '[{"en":"Mint gives an instant, refreshing cooling sensation","so":"Reexaantu (mint) waxay siisaa dareen qabow oo nafis leh isla markiiba"},{"en":"Smooth cream that massages easily into muscles and joints","so":"Kareem jilicsan oo si fudud loogu duugo murqaha iyo kalagoysyada"},{"en":"Herbal formula for external use only","so":"Isku-dar dhireed oo kaliya dibadda jirka loo isticmaalo"}]'::jsonb, null, null, null, null, array['chillflex-cream.webp']::text[], true, false, 0),
  ('aloe-vera', 'Aloe Vera (Aloe barbadensis)', 'Dacar (Aloe Vera)', null, array['Aloe barbadensis', 'Dacar', 'Aloe']::text[], (select id from public.categories where slug = 'herbal'), 'general', null, 'Aloe vera (Aloe barbadensis) — a succulent plant whose cooling inner-leaf gel is a classic of natural skin care. Ask our team on WhatsApp for the forms currently in stock.', 'Dacar (Aloe barbadensis) — geed caleemo buuran leh oo jel-ka qabow ee caleentiisa gudaha uu yahay mid caan ku ah daryeelka dabiiciga ah ee maqaarka. Kooxdayada WhatsApp ku weydii qaababka hadda kaydka ku jira.', '[{"en":"The inner-leaf gel has long been used to soothe and cool the skin","so":"Jel-ka caleenta gudaheeda muddo dheer ayaa loo isticmaalay dejinta iyo qaboojinta maqaarka"},{"en":"A traditional ingredient for moisturising skin and hair care","so":"Walax dhaqameed oo loo isticmaalo qoynta maqaarka iyo daryeelka timaha"},{"en":"Widely grown and used across the Horn of Africa and Arabia","so":"Si ballaaran ayaa loogu beeraa loona isticmaalaa Geeska Afrika iyo Carabta"}]'::jsonb, null, '{"en":"For external use only.","so":"Dibadda jirka oo keliya ayaa loo isticmaalaa."}'::jsonb, null, null, array['aloe-vera.webp']::text[], true, false, 1),
  ('neem', 'Neem (Azadirachta indica)', 'Neem (Azadirachta indica)', null, array['Azadirachta indica', 'Nim', 'Geed Hindi']::text[], (select id from public.categories where slug = 'herbal'), 'general', null, 'Neem (Azadirachta indica) — a hardy evergreen tree whose leaves and twigs have been used in traditional practice for centuries. Ask our team on WhatsApp for the forms currently in stock.', 'Neem (Azadirachta indica) — geed adag oo had iyo jeer cagaar ah, kaas oo caleemihiisa iyo laamihiisa qarniyo loo isticmaalayay dhaqan ahaan. Kooxdayada WhatsApp ku weydii qaababka hadda kaydka ku jira.', '[{"en":"Used for centuries in traditional Ayurvedic practice","so":"Qarniyo badan ayaa loo isticmaalayay dhaqanka Ayurveda"},{"en":"Leaves are traditionally used in natural skin and hair care","so":"Caleemaha dhaqan ahaan waxaa loo isticmaalaa daryeelka dabiiciga ah ee maqaarka iyo timaha"},{"en":"Twigs are a traditional natural chewing stick for cleaning teeth","so":"Laamaha waa caday dabiici ah oo dhaqan ahaan ilkaha lagu nadiifiyo"}]'::jsonb, null, '{"en":"Not for use during pregnancy or by young children. Ask a healthcare professional before taking neem internally.","so":"Looma isticmaalo xilliga uurka ama carruurta yaryar. Weydii xirfadle caafimaad ka hor inta aadan neem afka ka qaadan."}'::jsonb, null, null, array['neem.webp']::text[], true, false, 2),
  ('senna', 'Senna (Senna alexandrina)', 'Sanaa Makki (Senna)', null, array['Senna alexandrina', 'Sana Makki', 'Sanaa Makki', 'Cassia']::text[], (select id from public.categories where slug = 'herbal'), 'general', null, 'Senna (Senna alexandrina), known as Sanaa Makki — a well-known traditional herb from Arabia and the Horn of Africa. Ask our team on WhatsApp for the forms currently in stock.', 'Senna (Senna alexandrina), oo loo yaqaan Sanaa Makki — geed dhaqameed caan ah oo laga helo Carabta iyo Geeska Afrika. Kooxdayada WhatsApp ku weydii qaababka hadda kaydka ku jira.', '[{"en":"Well established for short-term relief of occasional constipation","so":"Si wanaagsan loo yaqaan oo loo isticmaalo muddo gaaban si loo yareeyo calool-fadhiga mararka qaar"},{"en":"Leaves and pods naturally contain compounds called sennosides","so":"Caleemaha iyo qolofta si dabiici ah waxay ka kooban yihiin walxo la yiraahdo sennosides"},{"en":"Long used in traditional Arabian and Prophetic medicine","so":"Muddo dheer ayaa loo isticmaalay daawada dhaqameed ee Carabta iyo Daawada Nabiga (Tibb Nabawi)"}]'::jsonb, null, '{"en":"Short-term use only — no more than one week without medical advice. Not for children under 12, during pregnancy or breastfeeding, or with abdominal pain.","so":"Muddo gaaban oo keliya — ha dhaafin hal toddobaad la''aanta talo caafimaad. Looma isticmaalo carruurta ka yar 12 sano, xilliga uurka ama naas-nuujinta, ama marka calooshu xanuunayso."}'::jsonb, null, null, array['senna.webp']::text[], true, false, 3),
  ('black-cumin', 'Black Cumin Seeds', 'Xabbad Sooda', null, array['Habbat al-Sawda', 'Nigella sativa', 'Xabbad Sooda', 'Habasoodo']::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', 'Whole seeds · Nigella sativa', 'Whole Nigella sativa seeds, cherished for generations in Somali and Middle Eastern kitchens and traditional wellness.', 'Xabbad sooda (Nigella sativa) oo dhan, jiil ka jiil qiimo ku lahayd jikada Soomaalida iyo Bariga Dhexe iyo fayo-qabka dhaqameed.', '[{"en":"Whole Nigella sativa seeds with a warm, peppery aroma","so":"Xabbad sooda oo dhan oo leh ur diirran oo basbaas u eg"},{"en":"Traditionally valued in prophetic and Middle Eastern wellness practice","so":"Dhaqan ahaan qiimo weyn ayay ku leedahay tibbiga nabawiga iyo fayo-qabka Bariga Dhexe"},{"en":"Versatile — add to bread, honey, tea or everyday dishes","so":"Siyaabo badan loo isticmaali karo — ku dar rootiga, malabka, shaaha ama cuntada maalinlaha ah"}]'::jsonb, null, null, null, null, array['black-cumin.webp']::text[], true, false, 4),
  ('chia-seeds', 'Chia Seeds', 'Iniinyaha Chia', null, '{}'::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', 'Whole seeds', 'Tiny, nutrient-dense seeds that swell into a soft gel — ideal for puddings, smoothies, yoghurt and juices.', 'Iniinyo yaryar oo nafaqo badan oo biyaha ku bararta oo noqota jel jilicsan — ku fiican macmacaanka, smoothie-ga, caanaha fadhiga iyo casiirka.', '[{"en":"Naturally rich in dietary fibre","so":"Dabiici ahaan hodan ku ah fiber-ka cuntada"},{"en":"Plant source of alpha-linolenic acid (ALA), an omega-3 fatty acid","so":"Il dhireed oo laga helo alpha-linolenic acid (ALA), oo ah dufan omega-3 ah"},{"en":"Easy to add to drinks, porridge and yoghurt","so":"Si fudud loogu dari karo cabbitaannada, boorashka iyo caanaha fadhiga"}]'::jsonb, null, null, null, null, array['chia-seeds.webp']::text[], true, false, 5),
  ('herbal-seeds', 'Herbal Seeds', 'Iniinyo Dhireed', null, '{}'::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', null, 'A selection of whole herbal seeds and dried botanicals. Ask our team on WhatsApp for the exact contents of the current selection.', 'Iniinyo dhireed oo dhan iyo dhir la qalajiyay oo la isku daray. Kooxdayada WhatsApp ku weydii waxa saxda ah ee ku jira xulashada hadda jirta.', null, null, null, null, null, array['herbal-seeds.webp']::text[], true, false, 6),
  ('pure-honey', 'Pure Honey', 'Malab Saafi ah', null, array['Malab', 'Honey']::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', null, 'Natural, pure honey with a rich golden colour and flavour — a timeless natural sweetener.', 'Malab dabiici ah oo saafi ah, leh midab dahabi ah iyo dhadhan qani ah — macmacaan dabiici ah oo weligiis qiimo lahaa.', '[{"en":"A natural source of carbohydrates for quick energy","so":"Il dabiici ah oo karbohaydraydh ah oo tamar degdeg ah bixisa"},{"en":"Delicious natural sweetener for tea, porridge and desserts","so":"Macmacaan dabiici ah oo dhadhan fiican leh oo shaaha, boorashka iyo macmacaanka lagu daro"},{"en":"Treasured in traditional and prophetic wellness practice","so":"Qiimo weyn ku leh fayo-qabka dhaqameed iyo tibbiga nabawiga"}]'::jsonb, null, '{"en":"Not suitable for babies under 12 months.","so":"Kuma habboona ilmaha ka yar 12 bilood."}'::jsonb, null, null, array['pure-honey.webp']::text[], true, true, 7),
  ('saffron', 'Saffron', 'Sacfaraan', null, array['Saffron Seeds', 'Sacfaraan', 'Zacfaraan']::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', 'Saffron threads', 'Delicate saffron threads with a deep colour and distinctive aroma — a little goes a long way.', 'Xarigo sacfaraan oo jilicsan, leh midab qoto dheer iyo ur gaar ah — wax yar ayaa ku filan.', '[{"en":"Prized spice that adds a rich golden colour and aroma","so":"Xawaash qaali ah oo siiya midab dahabi ah iyo ur fiican"},{"en":"A few threads are enough to flavour rice, tea and desserts","so":"Dhowr xarig ayaa ku filan in lagu dhadhamiyo bariiska, shaaha iyo macmacaanka"},{"en":"Long valued in traditional Middle Eastern and Persian practice","so":"Muddo dheer ayuu qiimo ku lahaa dhaqanka Bariga Dhexe iyo Faaris"}]'::jsonb, null, null, null, null, array['saffron.webp']::text[], true, false, 8),
  ('cloves', 'Cloves', 'Qaranfuul', null, '{}'::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', null, 'Whole aromatic cloves for tea, rice, and traditional Somali dishes. Ask our team on WhatsApp for details of the current stock.', 'Qaranfuul udgoon oo dhan oo loogu talagalay shaaha, bariiska iyo cuntooyinka dhaqameed ee Soomaalida. Kooxdayada WhatsApp ku weydii faahfaahinta kaydka hadda jira.', '[{"en":"Adds warm, rich aroma to tea, rice and stews","so":"Shaaha, bariiska iyo maraqa wuxuu siiyaa ur diiran oo qani ah"},{"en":"Naturally contains eugenol, an aromatic plant compound","so":"Si dabiici ah wuxuu ka kooban yahay eugenol, walax udgoon oo dhir ah"},{"en":"Long used in traditional home remedies and cooking","so":"Muddo dheer ayaa loo isticmaalay daawooyinka guriga iyo karinta dhaqameed"}]'::jsonb, null, null, null, null, array['star-anise.webp']::text[], true, false, 9),
  ('ceylon-cinnamon', 'Ceylon Cinnamon (Cinnamomum verum)', 'Qorfe (Ceylon Cinnamon)', null, array['Cinnamomum verum', 'Qorfe', 'Cinnamon', 'Darasiin']::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', null, 'Ceylon or "true" cinnamon (Cinnamomum verum) — fragrant quills with a delicate, sweet aroma. Ask our team on WhatsApp for the forms currently in stock.', 'Qorfe Ceylon ama qorfaha "dhabta ah" (Cinnamomum verum) — xabbado udgoon oo leh ur macaan oo jilicsan. Kooxdayada WhatsApp ku weydii qaababka hadda kaydka ku jira.', '[{"en":"True Ceylon cinnamon with a delicate, sweet aroma","so":"Qorfe Ceylon ah oo dhab ah, leh ur macaan oo jilicsan"},{"en":"Naturally lower in coumarin than common cassia cinnamon","so":"Si dabiici ah coumarin-keedu wuu ka yar yahay qorfaha caadiga ah ee cassia"},{"en":"A classic spice for shaah, rice and traditional Somali dishes","so":"Xawaash caan ah oo loogu talagalay shaaha, bariiska iyo cuntooyinka dhaqameed ee Soomaalida"}]'::jsonb, null, null, null, null, array['ceylon-cinnamon.webp']::text[], true, false, 10),
  ('coconut', 'Coconut (Cocos nucifera)', 'Qumbe (Coconut)', null, array['Cocos nucifera', 'Qumbe', 'Coconut']::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', null, 'Coconut (Cocos nucifera) — the versatile tropical palm behind coconut oil, milk and water. Ask our team on WhatsApp for the forms currently in stock.', 'Qumbe (Cocos nucifera) — geed timireed kulaal ah oo laga helo saliidda, caanaha iyo biyaha qumbaha. Kooxdayada WhatsApp ku weydii qaababka hadda kaydka ku jira.', null, null, null, null, null, array['coconut.webp']::text[], true, false, 11),
  ('turmeric-root', 'Turmeric Root (Curcuma longa)', 'Huruud (Turmeric)', null, array['Curcuma longa', 'Huruud', 'Turmeric', 'Kurkum']::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', null, 'Turmeric (Curcuma longa) — the golden root and spice prized in kitchens and traditional practice across Asia and Africa. Ask our team on WhatsApp for the forms currently in stock.', 'Huruud (Curcuma longa) — xidid iyo xawaash dahabi ah oo qiimo weyn ku leh jikada iyo dhaqanka Aasiya iyo Afrika. Kooxdayada WhatsApp ku weydii qaababka hadda kaydka ku jira.', '[{"en":"Golden spice that naturally contains curcumin","so":"Xawaash dahabi ah oo si dabiici ah uga kooban curcumin"},{"en":"Used for thousands of years in traditional Ayurvedic practice","so":"Kumanaan sano ayaa loo isticmaalayay dhaqanka Ayurveda"},{"en":"Adds warm colour and flavour to rice, stews and tea","so":"Bariiska, maraqa iyo shaaha wuxuu siiyaa midab iyo dhadhan diiran"}]'::jsonb, null, null, null, null, array['turmeric-root.webp']::text[], true, false, 12),
  ('moringa', 'Moringa (Moringa oleifera)', 'Moringa (Moringa oleifera)', null, array['Moringa oleifera', 'Drumstick tree', 'Mooringa']::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', null, 'Moringa (Moringa oleifera), the "drumstick tree" — its small green leaves are a traditional, nutrient-rich food. Ask our team on WhatsApp for the forms currently in stock.', 'Moringa (Moringa oleifera), oo loo yaqaan "drumstick tree" — caleemaheeda yaryar ee cagaarka ah waa cunto dhaqameed hodan ku ah nafaqo. Kooxdayada WhatsApp ku weydii qaababka hadda kaydka ku jira.', '[{"en":"Leaves naturally contain vitamins and minerals such as vitamin C, calcium and iron","so":"Caleemaha si dabiici ah waxay ka kooban yihiin fitamiinno iyo macdano sida fitamiin C, kaalshiyam iyo bir"},{"en":"Widely grown across East Africa and South Asia","so":"Si ballaaran ayaa looga beeraa Bariga Afrika iyo Koonfurta Aasiya"},{"en":"Dried leaves can be added to tea, food or smoothies","so":"Caleemaha la qalajiyay waxaa lagu dari karaa shaaha, cuntada ama cabitaannada"}]'::jsonb, null, null, null, null, array['moringa.webp']::text[], true, false, 13),
  ('rumi-mastagi', 'Rumi Mastagi (Mastic Gum)', 'Rumi Mastagi (Xabagta Mastic)', 'Kamphal', array['Mastic gum', 'Rumi mastagi', 'Mastika', 'Mastiki']::text[], (select id from public.categories where slug = 'herbal'), 'ingredients', '10 g', 'Rumi Mastagi — natural mastic gum resin from the mastic tree, packed by Kamphal for digestive wellness.', 'Rumi Mastagi — xabag dabiici ah oo laga helo geedka mastic, oo ay Kamphal u baakadaysay caafimaadka dheefshiidka.', '[{"en":"Natural resin from the mastic tree (Pistacia lentiscus)","so":"Xabag dabiici ah oo ka timaada geedka mastic (Pistacia lentiscus)"},{"en":"Traditionally chewed to freshen the breath","so":"Dhaqan ahaan waa la calaliyaa si afka loogu udgoonsiiyo"},{"en":"Long used in Middle Eastern and South Asian tradition for digestive wellness","so":"Muddo dheer ayaa loo isticmaalay dhaqanka Bariga Dhexe iyo Koonfurta Aasiya ee caafimaadka dheefshiidka"}]'::jsonb, null, null, null, null, array['rumi-mastic-gum.webp']::text[], true, false, 14),
  ('batana-oil', 'Batana Oil', null, 'Hualijia', '{}'::text[], (select id from public.categories where slug = 'herbal'), 'oils', '120 g · scalp & hair oil', 'A rich scalp and hair oil made with batana oil, traditionally used by the Miskito people of Honduras for hair care.', 'Saliid timo iyo madax oo qani ah oo laga sameeyay saliidda batana, dhaqan ahaan ay dadka Miskito ee Honduras u isticmaalaan daryeelka timaha.', '[{"en":"Rich, nourishing oil that conditions dry hair","so":"Saliid qani ah oo nafaqeysa, qoyana timaha qalalan"},{"en":"Helps soften hair and reduce the look of split ends","so":"Waxay gacan ka geysataa jilcinta timaha iyo yaraynta muuqaalka darfaha jaban"},{"en":"Massage into the scalp as part of a regular hair-care routine","so":"Ku duug maqaarka madaxa qayb ka mid ah daryeelka timaha ee joogtada ah"}]'::jsonb, null, null, null, null, array['batana-oil.webp']::text[], true, true, 15),
  ('feg-hair-spray', 'FEG Hair Spray', null, 'FEG', array['Feg Oil']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '50 ml spray', 'A scalp spray from FEG used as part of a hair-care routine. Ask our team for full ingredient and usage details.', 'Buufin madaxa ah oo ka timid FEG, loo isticmaalo qayb ka mid ah daryeelka timaha. Kooxdayada weydii faahfaahinta buuxda ee walxaha iyo isticmaalka.', null, null, null, null, null, array['feg-hair-spray.webp']::text[], true, false, 16),
  ('minoxidil-5', 'Minoxidil 5% Topical Solution', null, 'Kirkland Signature', array['Minoxidile']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '60 ml · 1-month supply · men', 'Extra-strength 5% minoxidil topical solution for men — an over-the-counter hair regrowth treatment for hereditary hair loss on the top of the scalp.', 'Dareere minoxidil 5% ah oo xoog badan oo loogu talagalay ragga — daawo aan warqad dhakhtar u baahnayn oo loo isticmaalo soo celinta timaha ka dhacay sababo hideed dhinaca sare ee madaxa.', '[{"en":"Contains 5% minoxidil, a clinically studied hair-regrowth ingredient","so":"Waxaa ku jira 5% minoxidil, walax si caafimaad ah loo daraaseeyay oo loogu talagalay soo celinta timaha"},{"en":"For hereditary hair thinning at the top of the scalp in men","so":"Loogu talagalay khafiifinta timaha ee hidaha ah ee dhinaca sare ee madaxa ragga"},{"en":"Unscented solution for daily use on the scalp","so":"Dareere aan ur lahayn oo maalin walba madaxa la mariyo"}]'::jsonb, null, '{"en":"Medicine for external use only. For men, as stated on the label. Speak to a pharmacist or doctor first if you have a heart condition or other health concerns.","so":"Daawo dibadda jirka oo keliya loo isticmaalo. Ragga ayaa loogu talagalay, sida ku qoran calaamadda. Marka hore la hadal farmashiiste ama dhakhtar haddii aad qabto xanuun wadne ama walaac kale oo caafimaad."}'::jsonb, null, null, array['minoxidil.webp']::text[], true, false, 17),
  ('rosemary-oil', 'Natural Rosemary Oil', 'Saliidda Rosemary', 'Nature Spell', array['Rosmery Oil']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '150 ml · hair & body oil', 'A natural treatment oil infused with rosemary, suitable for all hair and skin types.', 'Saliid dabiici ah oo lagu qasay rosemary, ku habboon dhammaan noocyada timaha iyo maqaarka.', '[{"en":"Conditions and adds shine to all hair types","so":"Waxay qoysaa oo dhalaal siisaa dhammaan noocyada timaha"},{"en":"Can be massaged into the scalp as part of a hair-care routine","so":"Waa lagu duugi karaa maqaarka madaxa qayb ka mid ah daryeelka timaha"},{"en":"Doubles as a nourishing body oil for skin","so":"Waxaa sidoo kale loo isticmaali karaa saliid jirka ah oo maqaarka nafaqeysa"}]'::jsonb, null, null, null, null, array['rosemary-oil.webp']::text[], true, false, 18),
  ('saliida-mucjisada', 'Saliida Mucjisada', 'Saliida Mucjisada', 'Somwell', array['Miracle Oil', 'Saliidda Mucjisada']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '300 ml · body massage oil spray', 'Somwell Miracle Oil — a relaxation body massage oil spray.', 'Somwell Miracle Oil — buufin saliid duugis jirka ah oo nasasho leh.', null, '[{"en":"Treats back pain, bone pain, headaches, fainting, and nerve issues — and the Holy Quran.","so":"Waxay daawaysaa xanuunka dhabarka, xanuunka lafaha, madax-xanuunka, suuxdinta, iyo dhibaatooyinka dareemayaasha — iyo Quraanka Kariimka ah."}]'::jsonb, null, null, null, array['saliida-mucjisada.webp']::text[], true, true, 19),
  ('saytuun-oil', 'Saytuun Oil (Extra Virgin Olive Oil)', 'Saliidda Saytuunka', 'Bestolio', array['Olive oil', 'Saytuun']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '100% extra virgin · first cold pressed · several sizes', '100% extra virgin olive oil, first cold pressed, with a great rich flavour — available in several bottle sizes.', 'Saliid saytuun 100% extra virgin ah, tuujin qabow oo koowaad ah, leh dhadhan qani ah — waxaa la helaa dhowr cabbir oo dhalo ah.', '[{"en":"Rich in monounsaturated fats (oleic acid)","so":"Hodan ku ah dufanka monounsaturated (oleic acid)"},{"en":"First cold pressed to keep its full natural flavour","so":"Tuujin qabow oo koowaad ah si dhadhankeeda dabiiciga ah loo ilaaliyo"},{"en":"Ideal for salads, cooking and traditional hair and skin care","so":"Ku fiican saladhka, karinta iyo daryeelka dhaqameed ee timaha iyo maqaarka"}]'::jsonb, null, null, null, null, array['saytuun-oil.webp']::text[], true, false, 20),
  ('argan-oil', 'Argan Oil', 'Saliidda Argan', 'Pure&Co', '{}'::text[], (select id from public.categories where slug = 'herbal'), 'oils', '1 litre · cosmetic grade · 100% natural', 'Pure&Co cosmetic-grade argan oil, 100% natural and vegan, in a generous 1-litre bottle for hair, skin and nails.', 'Saliidda argan ee Pure&Co oo heer qurxin ah, 100% dabiici ah oo vegan ah, ku jirta dhalo weyn oo 1 litir ah oo loogu talagalay timaha, maqaarka iyo ciddiyaha.', '[{"en":"Naturally rich in vitamin E and essential fatty acids","so":"Si dabiici ah hodan ugu ah fitamiin E iyo asiidhyada dufanka muhiimka ah"},{"en":"Conditions dry hair and adds shine","so":"Waxay qoysaa timaha qalalan oo dhalaal siisaa"},{"en":"Softens and moisturises skin and nails","so":"Waxay jilcisaa oo qoysaa maqaarka iyo ciddiyaha"}]'::jsonb, null, '{"en":"For external use only.","so":"Dibadda jirka oo keliya ayaa loo isticmaalaa."}'::jsonb, null, null, array['argan-oil.webp']::text[], true, false, 21),
  ('castor-oil', 'Organic Castor Oil', 'Saliidda Castor (Cayo)', 'Handcraft Blends', array['Castor oil', 'Custor oil', 'Ricinus communis']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '473 ml (16 fl oz) · USDA organic · hair, nails & skin', 'USDA-certified organic castor oil from Handcraft Blends — 100% pure and natural, pressed from the seeds of the castor plant (Ricinus communis).', 'Saliidda castor ee organic-ga ah ee Handcraft Blends, oo ay USDA aqoonsatay — 100% saafi iyo dabiici ah, laga tuujiyay iniinta geedka castor (Ricinus communis).', '[{"en":"USDA-certified organic, 100% pure castor oil, as labelled","so":"Saliid castor organic ah oo USDA aqoonsatay, 100% saafi ah, sida ku qoran calaamadda"},{"en":"Thick, rich oil traditionally used to condition hair, brows and lashes","so":"Saliid culus oo qani ah, dhaqan ahaan loo isticmaalo qoynta timaha, sunnaha iyo baalasha indhaha"},{"en":"Moisturises dry skin and nails","so":"Waxay qoysaa maqaarka iyo ciddiyaha qalalan"}]'::jsonb, null, '{"en":"For external use only.","so":"Dibadda jirka oo keliya ayaa loo isticmaalaa."}'::jsonb, '[{"en":"Handcraft Blends Organic Castor Oil","so":"Handcraft Blends Organic Castor Oil"},{"en":"The castor plant (Ricinus communis)","so":"Geedka castor (Ricinus communis)"}]'::jsonb, null, array['castor-oil.webp', 'castor-plant.webp']::text[], true, false, 22),
  ('avocado-oil', 'Avocado Oil', 'Saliidda Avocado', 'Sanoor', '{}'::text[], (select id from public.categories where slug = 'herbal'), 'oils', '60 ml · cold-pressed · 100% pure', 'Sanoor cold-pressed avocado oil made from California Hass avocados — a light, nourishing oil for face, body and hair.', 'Saliidda avocado ee Sanoor oo tuujin qabow ah, laga sameeyay avocado-ga Hass ee California — saliid fudud oo nafaqo leh oo loogu talagalay wejiga, jirka iyo timaha.', '[{"en":"Cold-pressed from Hass avocados, as labelled","so":"Tuujin qabow oo laga sameeyay avocado Hass, sida ku qoran calaamadda"},{"en":"Naturally rich in oleic acid and vitamin E","so":"Si dabiici ah hodan ugu ah oleic acid iyo fitamiin E"},{"en":"Light enough for face, body and hair care","so":"Waa fudud tahay oo ku habboon daryeelka wejiga, jirka iyo timaha"}]'::jsonb, null, '{"en":"For external use only.","so":"Dibadda jirka oo keliya ayaa loo isticmaalaa."}'::jsonb, null, null, array['avocado-oil.webp']::text[], true, false, 23),
  ('sesame-oil', 'Organic Sesame Oil', 'Saliidda Macsarka (Sesame)', 'GymBeam', array['Sesame oil', 'Bio sesame oil', 'Saliid macsar', 'Simsim']::text[], (select id from public.categories where slug = 'herbal'), 'oils', 'Organic (BIO) · cold-pressed', 'GymBeam BIO sesame oil — certified organic and cold-pressed, for cooking and traditional skin and hair care.', 'Saliidda sesame-ka ee GymBeam BIO — organic la aqoonsaday oo tuujin qabow ah, loogu talagalay karinta iyo daryeelka dhaqameed ee maqaarka iyo timaha.', '[{"en":"Certified organic, cold-pressed sesame oil, as labelled","so":"Saliid sesame organic ah oo tuujin qabow ah, sida ku qoran calaamadda"},{"en":"Naturally rich in unsaturated fats","so":"Si dabiici ah hodan ugu ah dufanka aan buuxsamin (unsaturated)"},{"en":"For cooking, or traditional skin and hair care","so":"Loogu talagalay karinta, ama daryeelka dhaqameed ee maqaarka iyo timaha"}]'::jsonb, null, null, null, null, array['sesame-oil.webp']::text[], true, false, 24),
  ('evening-primrose-oil', 'Evening Primrose Oil', 'Saliidda Evening Primrose', 'GymBeam', '{}'::text[], (select id from public.categories where slug = 'herbal'), 'oils', 'Softgel capsules', 'GymBeam evening primrose oil in easy softgel capsules — formulated for women''s health support and healthy skin and hair, as labelled.', 'Saliidda evening primrose ee GymBeam oo ku jirta kaabsuul jilicsan oo fudud — loogu talagalay taageerada caafimaadka haweenka iyo maqaarka iyo timaha caafimaadka qaba, sida ku qoran calaamadda.', '[{"en":"Natural source of gamma-linolenic acid (GLA), an omega-6 fatty acid","so":"Il dabiici ah oo gamma-linolenic acid (GLA) ah, kaas oo ah asiidh dufan omega-6 ah"},{"en":"Formulated for women''s health support, as labelled","so":"Loogu talagalay taageerada caafimaadka haweenka, sida ku qoran calaamadda"},{"en":"Easy-to-take softgel capsules","so":"Kaabsuul jilicsan oo si fudud loo qaato"}]'::jsonb, null, null, null, null, array['evening-primrose-oil.webp']::text[], true, false, 25),
  ('clove-oil', 'Clove Essential Oil', 'Saliidda Qaranfuulka', null, array['Clove oil', 'Qaranfuul oil', 'Eugenol']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '30 ml · 99% eugenol', 'Clove essential oil with 99% eugenol, as labelled — a warm, spicy oil distilled from clove buds.', 'Saliid udgoon oo qaranfuul ah oo leh 99% eugenol, sida ku qoran calaamadda — saliid diiran oo xawaash leh oo laga soo saaray ubaxa qaranfuulka.', '[{"en":"Rich in eugenol, clove''s natural aromatic compound","so":"Hodan ku ah eugenol, walaxda udgoon ee dabiiciga ah ee qaranfuulka"},{"en":"Traditionally used in dental care for its warming, numbing feel","so":"Dhaqan ahaan waxaa loo isticmaalaa daryeelka ilkaha sababtoo ah dareenkeeda diiran ee kabuubyada leh"},{"en":"Warm, spicy aroma for aromatherapy","so":"Ur diiran oo xawaash leh oo loogu talagalay daaweynta urta (aromatherapy)"}]'::jsonb, null, '{"en":"Concentrated essential oil — dilute with a carrier oil before applying to skin. Keep away from eyes and children. Do not swallow.","so":"Saliid udgoon oo xoog leh — ku qas saliid kale ka hor inta aadan maqaarka marin. Ka ilaali indhaha iyo carruurta. Ha liqin."}'::jsonb, null, null, array['clove-oil.webp']::text[], true, false, 26),
  ('ginger-oil', 'Ginger Essential Oil', 'Saliidda Sinjibiilka', null, array['Ginger oil', 'Sinjibiil', 'Zingiber officinale']::text[], (select id from public.categories where slug = 'herbal'), 'oils', null, 'Ginger essential oil, distilled from the root of the ginger plant (Zingiber officinale) — warm, spicy and invigorating.', 'Saliid udgoon oo sinjibiil ah, laga soo saaray xididka geedka sinjibiilka (Zingiber officinale) — diiran, xawaash leh oo firfircooni leh.', '[{"en":"Distilled from the ginger root (Zingiber officinale)","so":"Laga soo saaray xididka sinjibiilka (Zingiber officinale)"},{"en":"Popular in warming massage blends when diluted","so":"Caan ka ah isku-darka duugista ee diirran marka la khafiifiyo"},{"en":"Warm, spicy aroma traditionally used in aromatherapy","so":"Ur diiran oo xawaash leh oo dhaqan ahaan loo isticmaalo daaweynta urta"}]'::jsonb, null, '{"en":"Concentrated essential oil — dilute with a carrier oil before applying to skin. Keep away from eyes and children. Do not swallow.","so":"Saliid udgoon oo xoog leh — ku qas saliid kale ka hor inta aadan maqaarka marin. Ka ilaali indhaha iyo carruurta. Ha liqin."}'::jsonb, null, null, array['ginger-oil.webp']::text[], true, false, 27),
  ('myrrh-oil', 'Myrrh Essential Oil (Commiphora myrrha)', 'Saliidda Malmalka (Myrrh)', null, array['Myrrh', 'Malmal', 'Commiphora myrrha']::text[], (select id from public.categories where slug = 'herbal'), 'oils', null, 'Myrrh essential oil from Commiphora myrrha resin — the classic aromatic resin of Somalia and the Horn of Africa.', 'Saliid udgoon oo malmal ah oo laga helo xabagta Commiphora myrrha — xabagta udgoon ee caanka ah ee Soomaaliya iyo Geeska Afrika.', '[{"en":"Distilled from myrrh resin, a traditional product of Somalia and the Horn of Africa","so":"Laga soo saaray xabagta malmalka, oo ah wax-soo-saar dhaqameed oo Soomaaliya iyo Geeska Afrika ah"},{"en":"Used since ancient times in perfumes, incense and skin care","so":"Tan iyo waqtiyadii hore ayaa loo isticmaalayay cadarrada, uunsiga iyo daryeelka maqaarka"},{"en":"Rich, warm, earthy aroma for aromatherapy","so":"Ur qani ah, diiran oo ciid u eg oo loogu talagalay daaweynta urta"}]'::jsonb, null, '{"en":"Concentrated essential oil — dilute with a carrier oil before applying to skin. Keep away from eyes and children. Do not swallow.","so":"Saliid udgoon oo xoog leh — ku qas saliid kale ka hor inta aadan maqaarka marin. Ka ilaali indhaha iyo carruurta. Ha liqin."}'::jsonb, null, null, array['myrrh-oil.webp']::text[], true, false, 28),
  ('carrot-seed-oil', 'Carrot Seed Essential Oil', 'Saliidda Iniinta Karootada', 'Sameera', array['Carrot seed oil', 'Daucus carota']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '15 ml · 100% pure & natural', 'Sameera carrot seed essential oil — 100% pure and natural, distilled from the seeds of the wild carrot.', 'Saliidda udgoon ee iniinta karootada ee Sameera — 100% saafi iyo dabiici ah, laga soo saaray iniinta karootada duurka.', '[{"en":"Distilled from wild carrot seeds (Daucus carota)","so":"Laga soo saaray iniinta karootada duurka (Daucus carota)"},{"en":"Popular in natural skin-care blends when diluted","so":"Caan ka ah isku-darka dabiiciga ah ee daryeelka maqaarka marka la khafiifiyo"},{"en":"Warm, earthy aroma for aromatherapy","so":"Ur diiran oo ciid u eg oo loogu talagalay daaweynta urta"}]'::jsonb, null, '{"en":"Concentrated essential oil — dilute with a carrier oil before applying to skin. Keep away from eyes and children. Do not swallow.","so":"Saliid udgoon oo xoog leh — ku qas saliid kale ka hor inta aadan maqaarka marin. Ka ilaali indhaha iyo carruurta. Ha liqin."}'::jsonb, null, null, array['carrot-seed-oil.webp']::text[], true, false, 29),
  ('rosemary-essential-oil', 'Rosemary Essential Oil', 'Saliidda Udgoon ee Rosemary', null, array['Rosmery oil', 'Rosemary oil']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '60 ml (2.02 fl oz) · steam distilled · 100% pure', 'Steam-distilled, 100% pure rosemary essential oil with a dropper, made for hair-growth and scalp-care routines, as labelled.', 'Saliid udgoon oo rosemary ah oo 100% saafi ah, la uumi-sifeeyay, leh dhibcis, loogu talagalay daryeelka korriinka timaha iyo maqaarka madaxa, sida ku qoran calaamadda.', '[{"en":"Steam-distilled, 100% pure rosemary essential oil, as labelled","so":"Saliid udgoon oo rosemary ah, la uumi-sifeeyay, 100% saafi ah, sida ku qoran calaamadda"},{"en":"Popular for scalp massage in hair-care routines when diluted","so":"Caan u ah duugista maqaarka madaxa ee daryeelka timaha marka la khafiifiyo"},{"en":"Fresh, herbal aroma for aromatherapy","so":"Ur cusub oo dhireed ah oo loogu talagalay daaweynta urta"}]'::jsonb, null, '{"en":"Concentrated essential oil — dilute with a carrier oil before applying to skin. Keep away from eyes and children. Do not swallow.","so":"Saliid udgoon oo xoog leh — ku qas saliid kale ka hor inta aadan maqaarka marin. Ka ilaali indhaha iyo carruurta. Ha liqin."}'::jsonb, null, null, array['rosemary-essential-oil.webp']::text[], true, false, 30),
  ('black-seed-oil', 'Black Seed Oil (Nigella sativa)', 'Saliidda Xabbad Sooda', 'Herbal Goodness', array['Black seed oil', 'Nigella sativa', 'Xabbad Sooda', 'Habbat al-Sawda']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '240 ml (8 fl oz)', 'Herbal Goodness black seed oil from Nigella sativa — the black seed treasured in Somali homes and Prophetic medicine.', 'Saliidda xabbad sooda ee Herbal Goodness oo laga helo Nigella sativa — iniinta madow ee qiimaha weyn ku leh guryaha Soomaalida iyo Daawada Nabiga.', '[{"en":"Pressed from the seeds of Nigella sativa (black seed)","so":"Laga tuujiyay iniinta Nigella sativa (xabbad sooda)"},{"en":"Naturally contains thymoquinone, black seed''s key compound","so":"Si dabiici ah waxay ka kooban tahay thymoquinone, walaxda ugu muhiimsan xabbad sooda"},{"en":"Valued in Prophetic medicine and Somali households for generations","so":"Qiimo weyn ayay ku leedahay Daawada Nabiga iyo guryaha Soomaalida jiilal badan"}]'::jsonb, null, null, '[{"en":"Herbal Goodness Black Seed Oil","so":"Herbal Goodness Black Seed Oil"},{"en":"The black seed flower (Nigella sativa)","so":"Ubaxa xabbad sooda (Nigella sativa)"}]'::jsonb, null, array['black-seed-oil.webp', 'nigella-sativa-flower.webp']::text[], true, false, 31),
  ('tea-tree-oil', 'Tea Tree Oil', 'Saliidda Tea Tree', 'Spring Valley', array['Tea tree', 'Melaleuca alternifolia']::text[], (select id from public.categories where slug = 'herbal'), 'oils', '60 ml (2 fl oz) · 100% pure · skin health', 'Spring Valley 100% pure tea tree oil, derived from the Melaleuca alternifolia tree, made for skin-health routines as labelled.', 'Saliidda tea tree ee Spring Valley oo 100% saafi ah, laga soo saaray geedka Melaleuca alternifolia, loogu talagalay daryeelka caafimaadka maqaarka sida ku qoran calaamadda.', '[{"en":"100% pure tea tree oil from Melaleuca alternifolia, as labelled","so":"Saliid tea tree oo 100% saafi ah oo ka timid Melaleuca alternifolia, sida ku qoran calaamadda"},{"en":"Formulated for skin health — dilute before applying, as directed","so":"Loogu talagalay caafimaadka maqaarka — khafiifi ka hor inta aadan marin, sida lagu tilmaamay"},{"en":"Fresh, clean aroma for aromatherapy","so":"Ur cusub oo nadiif ah oo loogu talagalay daaweynta urta"}]'::jsonb, null, '{"en":"Concentrated essential oil — dilute with a carrier oil before applying to skin. Keep away from eyes and children. Do not swallow.","so":"Saliid udgoon oo xoog leh — ku qas saliid kale ka hor inta aadan maqaarka marin. Ka ilaali indhaha iyo carruurta. Ha liqin."}'::jsonb, null, null, array['tea-tree-oil.webp']::text[], true, false, 32),
  ('ashwagandha-gummies', 'Ashwagandha Gummies', null, 'New Leaf', '{}'::text[], (select id from public.categories where slug = 'supplements'), null, '1200 mg · 5% withanolides · 180 gummies', 'Vegan ashwagandha gummies made with real fruit juice — an easy way to add this traditional Ayurvedic herb to your daily routine.', 'Xabbado macaan oo vegan ah oo ashwagandha ah, laga sameeyay casiir miro dhab ah — hab fudud oo aad geedkan dhaqameed ee Ayurveda ugu darto nidaamkaaga maalinlaha ah.', '[{"en":"Traditionally used in Ayurveda as an adaptogen to support calm and balance","so":"Dhaqan ahaan Ayurveda waxaa loo isticmaalaa sidii adaptogen si loo taageero degganaanta iyo dheelitirka"},{"en":"Standardised to 5% withanolides, the herb''s key natural compounds","so":"Waxaa lagu habeeyay 5% withanolides, oo ah walxaha dabiiciga ah ee ugu muhiimsan geedka"},{"en":"Vegan, lab-tested gummies — no capsules to swallow","so":"Xabbado vegan ah oo shaybaar lagu baaray — looma baahna kaabsuul la liqo"}]'::jsonb, null, null, null, null, array['ashwagandha.webp']::text[], true, true, 33),
  ('fenugreek', 'Fenugreek', 'Xulbad (Fenugreek)', 'NOW', array['Fengruuk', 'Xulbad', 'Hulbad']::text[], (select id from public.categories where slug = 'supplements'), null, '500 mg · 100 veg capsules', 'Fenugreek seed in convenient 500 mg vegetarian capsules — a traditional herb long used in Somali, Middle Eastern and South Asian homes.', 'Iniinta xulbadda oo ku jirta kaabsuul khudradeed oo 500 mg ah — geed dhaqameed muddo dheer laga isticmaali jiray guryaha Soomaalida, Bariga Dhexe iyo Koonfurta Aasiya.', '[{"en":"Traditional herb long valued in Middle Eastern and South Asian herbal practice","so":"Geed dhaqameed oo muddo dheer qiimo ku lahaa daawada dhireed ee Bariga Dhexe iyo Koonfurta Aasiya"},{"en":"Traditionally used to support healthy digestion","so":"Dhaqan ahaan waxaa loo isticmaalaa taageeridda dheefshiid caafimaad qaba"},{"en":"Vegetarian / vegan capsules","so":"Kaabsuul khudradeed / vegan ah"}]'::jsonb, null, null, null, null, array['fenugreek.webp']::text[], true, false, 34),
  ('magnesium-glycinate', 'Magnesium Glycinate', null, 'New Leaf', '{}'::text[], (select id from public.categories where slug = 'supplements'), null, '120 capsules', 'Magnesium in its gentle glycinate form — a well-tolerated choice for everyday mineral support.', 'Magnesium oo ku jira qaabka glycinate ee jilicsan — doorasho uu jirku si fiican u qaato oo loogu talagalay taageerada macdanta maalinlaha ah.', '[{"en":"Magnesium contributes to the reduction of tiredness and fatigue","so":"Magnesium-ku wuxuu gacan ka geystaa yaraynta daalka iyo tabar-darrida"},{"en":"Magnesium contributes to normal muscle function","so":"Magnesium-ku wuxuu gacan ka geystaa shaqada caadiga ah ee murqaha"},{"en":"Magnesium contributes to the normal function of the nervous system","so":"Magnesium-ku wuxuu gacan ka geystaa shaqada caadiga ah ee habdhiska dareemayaasha"}]'::jsonb, null, null, null, null, array['magnesium-glycinate.webp']::text[], true, true, 35),
  ('prostate-plus', 'Prostate Plus', null, 'Earth''s Creation', '{}'::text[], (select id from public.categories where slug = 'supplements'), null, '60 capsules · with saw palmetto', 'A men''s prostate health formula with added saw palmetto, as described by the manufacturer.', 'Isku-dar loogu talagalay caafimaadka qanjirka ''prostate'' ee ragga, oo lagu daray saw palmetto, sida ay shirkadda soo saartay sheegtay.', '[{"en":"Formulated for men''s prostate health, as labelled by the manufacturer","so":"Waxaa loo sameeyay caafimaadka qanjirka ''prostate'' ee ragga, sida shirkaddu ku qortay calaamadda"},{"en":"Contains saw palmetto, a botanical traditionally used in men''s health","so":"Waxaa ku jira saw palmetto, geed dhaqan ahaan loo isticmaalo caafimaadka ragga"},{"en":"Non-GMO dietary supplement made in the USA","so":"Kaab cunto oo aan GMO ahayn, laguna sameeyay Maraykanka"}]'::jsonb, null, '{"en":"Men with urinary or prostate symptoms should see a doctor before use.","so":"Ragga qaba calaamado kaadi ama ''prostate'' la xiriira waa inay dhakhtar arkaan ka hor isticmaalka."}'::jsonb, null, null, array['prostate-plus.webp']::text[], true, false, 36),
  ('shilajit-ultra', 'Shilajit Ultra', null, 'Flynew', '{}'::text[], (select id from public.categories where slug = 'supplements'), null, '60 capsules', 'Shilajit in easy capsule form — a mineral-rich resin traditionally gathered from high mountain rocks.', 'Shilajit oo ku jira kaabsuul fudud — xab hodan ku ah macdano, dhaqan ahaan laga soo ururiyo dhagxaanta buuraha dhaadheer.', '[{"en":"Traditional Ayurvedic resin, naturally rich in fulvic acid","so":"Xab dhaqameed Ayurveda ah oo dabiici ahaan hodan ku ah fulvic acid"},{"en":"Easy-to-take capsules — no measuring of resin needed","so":"Kaabsuul si fudud loo qaato — looma baahna in xabka la miisaamo"},{"en":"Made in the USA, as stated on the label","so":"Waxaa lagu sameeyay Maraykanka, sida ku qoran calaamadda"}]'::jsonb, null, null, null, null, array['shilajit-ultra.webp']::text[], true, false, 37),
  ('shilajit-gummies', 'Shilajit Gummies', null, 'New Leaf', '{}'::text[], (select id from public.categories where slug = 'supplements'), null, '3000 mg · with zinc & vitamin B6 · 60 gummies', 'Berry-flavoured shilajit gummies with added zinc and vitamin B6 — a modern, easy way to enjoy this traditional resin.', 'Xabbado macaan oo shilajit ah oo dhadhan berry leh, lagu daray zinc iyo fitamiin B6 — hab casri ah oo fudud oo lagu isticmaalo xabkan dhaqameed.', '[{"en":"Zinc contributes to the normal function of the immune system","so":"Zinc-gu wuxuu gacan ka geystaa shaqada caadiga ah ee habdhiska difaaca jirka"},{"en":"Vitamin B6 contributes to the reduction of tiredness and fatigue","so":"Fitamiin B6 wuxuu gacan ka geystaa yaraynta daalka iyo tabar-darrida"},{"en":"Vegan, berry-flavoured gummies made in the EU","so":"Xabbado macaan oo vegan ah, dhadhan berry leh, laguna sameeyay Midowga Yurub"}]'::jsonb, null, null, null, null, array['shilajit-gummies.webp']::text[], true, true, 38),
  ('collagen-beauty-gummies', 'Collagen Beauty Gummies', 'Kolajin (Collagen) Gummies', 'New Leaf', '{}'::text[], (select id from public.categories where slug = 'supplements'), null, 'Hydrolysed bovine collagen I & III · vitamin C, folic acid & biotin · 60 gummies', 'Strawberry-flavoured gummies with hydrolysed collagen, vitamin C, folic acid and biotin for your daily beauty routine.', 'Xabbado macaan oo dhadhan istroberi leh oo ka kooban kolajin la jajabiyay, fitamiin C, folic acid iyo biotin, loogu talagalay quruxda maalinlaha ah.', '[{"en":"Vitamin C contributes to normal collagen formation for healthy skin","so":"Fitamiin C wuxuu gacan ka geystaa samaynta caadiga ah ee kolajinka si maqaarku u caafimaad qabo"},{"en":"Biotin contributes to the maintenance of normal hair and skin","so":"Biotin-ku wuxuu gacan ka geystaa ilaalinta timo iyo maqaar caadi ah"},{"en":"Hydrolysed bovine collagen types I & III in a tasty gummy","so":"Kolajin lo''aad (nooca I & III) oo la jajabiyay, ku jira xabbad macaan"}]'::jsonb, null, null, null, null, array['collagen.webp']::text[], true, true, 39),
  ('dhea-25', 'DHEA 25 mg', null, 'Earth''s Creation', '{}'::text[], (select id from public.categories where slug = 'supplements'), null, '25 mg per serving · 60 capsules', 'DHEA (dehydroepiandrosterone), 25 mg per serving — a hormone precursor that the body''s adrenal glands naturally produce.', 'DHEA (dehydroepiandrosterone), 25 mg qaadasho kasta — hormoon ay qanjirada adrenal-ka ee jirku si dabiici ah u sameeyaan.', '[{"en":"DHEA is a hormone naturally produced by the adrenal glands","so":"DHEA waa hormoon ay dabiici ahaan sameeyaan qanjirada adrenal-ka"},{"en":"Provides 25 mg of DHEA per serving","so":"Qaadasho kasta waxay bixisaa 25 mg oo DHEA ah"},{"en":"Non-GMO capsules made in the USA","so":"Kaabsuul aan GMO ahayn oo lagu sameeyay Maraykanka"}]'::jsonb, null, '{"en":"DHEA is a hormone. Use only after speaking with a doctor. Not for under-18s or for pregnant or breastfeeding women.","so":"DHEA waa hormoon. Isticmaal oo keliya kadib markaad la hadasho dhakhtar. Looma talagelin dadka ka yar 18 sano ama haweenka uurka leh ama naas-nuujinaya."}'::jsonb, null, null, array['dhea.webp']::text[], true, false, 40),
  ('inositol-capsules', 'Inositol Capsules 500 mg', null, 'NOW', '{}'::text[], (select id from public.categories where slug = 'supplements'), null, '500 mg · myo-inositol · 100 veg capsules', 'Inositol in its natural myo-inositol form, in 500 mg vegetarian capsules.', 'Inositol oo ku jira qaabkiisa dabiiciga ah ee myo-inositol, kaabsuul khudradeed oo 500 mg ah.', '[{"en":"Provides myo-inositol, the most common natural form of inositol","so":"Wuxuu bixiyaa myo-inositol, qaabka dabiiciga ah ee ugu badan ee inositol"},{"en":"Supports healthy cell membrane function, as labelled","so":"Wuxuu taageeraa shaqada caafimaadka qabta ee xuubka unugyada, sida ku qoran calaamadda"},{"en":"Vegetarian / vegan capsules","so":"Kaabsuul khudradeed / vegan ah"}]'::jsonb, null, null, null, null, array['inositol.webp']::text[], true, false, 41),
  ('iron-complex', 'Iron Complex', 'Bir (Iron Complex)', 'NOW', '{}'::text[], (select id from public.categories where slug = 'supplements'), null, '100 tablets · bioavailable iron', 'A bioavailable, gentle iron complex — an essential mineral for everyday energy.', 'Isku-dar bir ah oo jirku si fiican u nuugo oo jilicsan — macdan muhiim u ah tamarta maalinlaha ah.', '[{"en":"Iron contributes to the normal formation of red blood cells and haemoglobin","so":"Birtu waxay gacan ka geysataa samaynta caadiga ah ee unugyada dhiigga cas iyo haemoglobin-ka"},{"en":"Iron contributes to normal oxygen transport in the body","so":"Birtu waxay gacan ka geysataa qaadista caadiga ah ee ogsijiinta jirka"},{"en":"Iron contributes to the reduction of tiredness and fatigue","so":"Birtu waxay gacan ka geysataa yaraynta daalka iyo tabar-darrida"}]'::jsonb, null, '{"en":"Keep out of reach of children — too much iron is dangerous for young children.","so":"Ka fogee carruurta — bir badan ayaa khatar ku ah carruurta yaryar."}'::jsonb, null, null, array['iron-complex.webp']::text[], true, false, 42),
  ('ultra-omega-3', 'Ultra Omega-3 Fish Oil', null, 'NOW', '{}'::text[], (select id from public.categories where slug = 'supplements'), null, '500 EPA / 250 DHA · 90 softgels', 'Concentrated fish oil with 500 mg EPA and 250 mg DHA in odour-controlled, enteric-coated softgels.', 'Saliid kalluun oo xoogan oo leh 500 mg EPA iyo 250 mg DHA, ku jira kaabsuul jilicsan oo urta la xakameeyay oo dahaar caloosha ilaaliya leh.', '[{"en":"EPA and DHA contribute to the normal function of the heart","so":"EPA iyo DHA waxay gacan ka geystaan shaqada caadiga ah ee wadnaha"},{"en":"DHA contributes to the maintenance of normal brain function","so":"DHA wuxuu gacan ka geystaa ilaalinta shaqada caadiga ah ee maskaxda"},{"en":"Odour-controlled, enteric-coated softgels","so":"Kaabsuul jilicsan oo urta la xakameeyay, dahaar caloosha ilaaliya leh"}]'::jsonb, null, null, null, null, array['ultra-omega-3.webp']::text[], true, true, 43),
  ('zinc-50', 'Zinc 50 mg', null, 'NOW', '{}'::text[], (select id from public.categories where slug = 'supplements'), null, '50 mg · 100 tablets', 'Essential zinc in 50 mg tablets for everyday immune and enzyme support.', 'Zinc muhiim ah oo ku jira kiniin 50 mg ah, loogu talagalay taageerada maalinlaha ah ee difaaca jirka iyo enzymes-ka.', '[{"en":"Zinc contributes to the normal function of the immune system","so":"Zinc-gu wuxuu gacan ka geystaa shaqada caadiga ah ee habdhiska difaaca jirka"},{"en":"Zinc contributes to normal enzyme function and metabolism","so":"Zinc-gu wuxuu gacan ka geystaa shaqada caadiga ah ee enzymes-ka iyo dheef-shiid kiimikaadka"},{"en":"Zinc contributes to the maintenance of normal skin, hair and nails","so":"Zinc-gu wuxuu gacan ka geystaa ilaalinta maqaar, timo iyo ciddiyo caadi ah"}]'::jsonb, null, null, null, null, array['zinc.webp']::text[], true, false, 44),
  ('zinc-picolinate', 'Zinc Picolinate 50 mg', null, 'NOW', '{}'::text[], (select id from public.categories where slug = 'supplements'), null, '50 mg · 40 veg capsules', 'Zinc in picolinate form, a chelated zinc, in 50 mg vegetarian capsules.', 'Zinc oo ku jira qaabka picolinate (zinc chelated ah), kaabsuul khudradeed oo 50 mg ah.', '[{"en":"Zinc contributes to the normal function of the immune system","so":"Zinc-gu wuxuu gacan ka geystaa shaqada caadiga ah ee habdhiska difaaca jirka"},{"en":"Zinc contributes to the maintenance of normal skin","so":"Zinc-gu wuxuu gacan ka geystaa ilaalinta maqaar caadi ah"},{"en":"Vegetarian / vegan capsules","so":"Kaabsuul khudradeed / vegan ah"}]'::jsonb, null, null, null, null, array['zinc-picolinate.webp']::text[], true, false, 45),
  ('d-mannose', 'D-Mannose 500 mg', null, 'NOW', array['Mannose', 'Urinary support']::text[], (select id from public.categories where slug = 'supplements'), null, '500 mg · 60 veg capsules', 'D-mannose, a naturally occurring simple sugar, in 500 mg vegetarian capsules — formulated by NOW for urinary tract support.', 'D-mannose, oo ah sonkor fudud oo dabiici ahaan jirta, ku jirta kaabsuul khudradeed oo 500 mg ah — NOW waxay u samaysay taageerada kanaalka kaadida.', '[{"en":"Formulated for urinary tract support, as labelled by the manufacturer","so":"Loogu talagalay taageerada kanaalka kaadida, sida ay shirkaddu ku qortay calaamadda"},{"en":"D-mannose is a simple sugar found naturally in fruits such as cranberries","so":"D-mannose waa sonkor fudud oo si dabiici ah looga helo miraha sida cranberry"},{"en":"Vegetarian / vegan capsules","so":"Kaabsuul khudradeed / vegan ah"}]'::jsonb, null, '{"en":"Not a substitute for medical treatment. If you have symptoms of a urinary infection, see a doctor.","so":"Ma beddelo daaweyn caafimaad. Haddii aad qabto calaamado caabuq kaadi, dhakhtar u tag."}'::jsonb, null, null, array['d-mannose.webp']::text[], true, false, 46),
  ('probiotic-acidophilus', 'Probiotic Acidophilus', null, 'Earth''s Creation', array['Acidophilus', 'Probiotic']::text[], (select id from public.categories where slug = 'supplements'), null, '500 million per serving · 60 capsules', 'Earth''s Creation Probiotic Acidophilus — Lactobacillus acidophilus in delayed-release capsules for digestive support, as labelled.', 'Earth''s Creation Probiotic Acidophilus — Lactobacillus acidophilus ku jira kaabsuul si tartiib ah u furma, loogu talagalay taageerada dheefshiidka, sida ku qoran calaamadda.', '[{"en":"500 million Lactobacillus acidophilus per serving, as labelled","so":"500 milyan oo Lactobacillus acidophilus ah qaadasho kasta, sida ku qoran calaamadda"},{"en":"Delayed-release capsules designed for absorption in the intestine, as stated by the manufacturer","so":"Kaabsuul si tartiib ah u furma oo loogu talagalay in mindhicirka lagu nuugo, sida ay shirkaddu sheegtay"},{"en":"Formulated to help balance intestinal microflora, as labelled","so":"Loogu talagalay inuu gacan ka geysto dheelitirka bakteeriyada wanaagsan ee mindhicirka, sida ku qoran calaamadda"}]'::jsonb, null, null, null, null, array['probiotic-acidophilus.webp']::text[], true, false, 47),
  ('probiotic-multi-strain', 'Probiotic Multi Strain', null, 'New Leaf', array['Probiotic', 'Multi strain probiotic']::text[], (select id from public.categories where slug = 'supplements'), null, '6 billion CFU · 5 strains · 120 tablets', 'New Leaf high-strength multi-strain probiotic — 6 billion CFU from five live cultures in each serving, as labelled.', 'New Leaf probiotic xoog badan oo noocyo badan leh — 6 bilyan CFU oo ka yimid shan nooc oo bakteeriya nool ah qaadasho kasta, sida ku qoran calaamadda.', '[{"en":"High strength: 6 billion CFU per serving, as labelled","so":"Xoog badan: 6 bilyan CFU qaadasho kasta, sida ku qoran calaamadda"},{"en":"Five strains: L. acidophilus, B. bifidum, L. rhamnosus, L. salivarius and S. thermophilus","so":"Shan nooc: L. acidophilus, B. bifidum, L. rhamnosus, L. salivarius iyo S. thermophilus"},{"en":"Easy-to-take tablets for daily use","so":"Kiniin si fudud loo qaato oo maalin walba ah"}]'::jsonb, null, null, null, null, array['probiotic-multi-strain.webp']::text[], true, false, 48),
  ('folic-acid', 'Folic Acid 800 mcg with Vitamin B-12', null, 'NOW', array['Folate', 'Folic acid']::text[], (select id from public.categories where slug = 'supplements'), null, '800 mcg · with vitamin B-12 · 250 tablets', 'NOW Folic Acid 800 mcg with added vitamin B-12 — a B-complex vitamin supporting healthy homocysteine metabolism, as labelled.', 'NOW Folic Acid 800 mcg oo lagu daray fitamiin B-12 — fitamiin B-complex ah oo taageera dheef-shiidka caafimaadka qaba ee homocysteine, sida ku qoran calaamadda.', '[{"en":"Folate contributes to normal blood formation","so":"Folate wuxuu gacan ka geystaa samaynta caadiga ah ee dhiigga"},{"en":"Folate contributes to maternal tissue growth during pregnancy","so":"Folate wuxuu gacan ka geystaa korriinka unugyada hooyada xilliga uurka"},{"en":"Folate and vitamin B12 contribute to normal homocysteine metabolism","so":"Folate iyo fitamiin B12 waxay gacan ka geystaan dheef-shiidka caadiga ah ee homocysteine"}]'::jsonb, null, null, null, null, array['folic-acid.webp']::text[], true, false, 49),
  ('hair-skin-nails-gummies', 'Hair, Skin & Nails Gummies', null, 'Earth''s Creation', array['Biotin', 'Hair skin nails']::text[], (select id from public.categories where slug = 'supplements'), null, 'Biotin 5,000 mcg · strawberry · 60 gummies', 'Earth''s Creation Hair, Skin & Nails — strawberry-flavoured gummies with 5,000 mcg biotin, made for beauty from within.', 'Earth''s Creation Hair, Skin & Nails — xabbado macaan oo dhadhan strawberry leh oo ay ku jirto 5,000 mcg biotin, loogu talagalay quruxda gudaha ka timaada.', '[{"en":"Biotin contributes to the maintenance of normal hair","so":"Biotin wuxuu gacan ka geystaa ilaalinta timo caadi ah"},{"en":"Biotin contributes to the maintenance of normal skin","so":"Biotin wuxuu gacan ka geystaa ilaalinta maqaar caadi ah"},{"en":"Strawberry-flavoured gummies — no capsules to swallow","so":"Xabbado macaan oo dhadhan strawberry leh — looma baahna kaabsuul la liqo"}]'::jsonb, null, null, null, null, array['hair-skin-nails-gummies.webp']::text[], true, false, 50),
  ('calcium-magnesium', 'Calcium & Magnesium', null, 'NOW', array['Cal Mag', 'Calcium magnesium']::text[], (select id from public.categories where slug = 'supplements'), null, '2:1 ratio · 100 tablets', 'NOW Calcium & Magnesium in a 2:1 ratio — high in both minerals for everyday bone health support, as labelled.', 'NOW Calcium & Magnesium oo saami 2:1 ah — labadan macdanba ku badan, loogu talagalay taageerada maalinlaha ah ee caafimaadka lafaha, sida ku qoran calaamadda.', '[{"en":"Calcium is needed for the maintenance of normal bones","so":"Kaalshiyamku waxaa loo baahan yahay ilaalinta lafo caadi ah"},{"en":"Magnesium contributes to normal muscle function","so":"Magnesium-ku wuxuu gacan ka geystaa shaqada caadiga ah ee murqaha"},{"en":"Calcium and magnesium in a 2:1 ratio, as labelled","so":"Kaalshiyam iyo magnesium oo saami 2:1 ah, sida ku qoran calaamadda"}]'::jsonb, null, null, null, null, array['calcium-magnesium.webp']::text[], true, false, 51),
  ('collagen-peptides', 'Collagen Peptides (Type I, II & III)', null, 'Earth''s Creation', array['Collagen powder', 'Hydrolyzed collagen']::text[], (select id from public.categories where slug = 'supplements'), null, '4,000 mg per serving · 188.7 g powder', 'Earth''s Creation hydrolysed collagen peptides (types I, II & III) in powder form, made to support hair, skin, nails, bones and joints, as labelled.', 'Earth''s Creation collagen peptides la jajabiyay (noocyada I, II & III) oo budo ah, loogu talagalay taageerada timaha, maqaarka, ciddiyaha, lafaha iyo kalagoysyada, sida ku qoran calaamadda.', '[{"en":"4,000 mg hydrolysed collagen peptides (types I, II & III) per serving, as labelled","so":"4,000 mg collagen peptides la jajabiyay (noocyada I, II & III) qaadasho kasta, sida ku qoran calaamadda"},{"en":"Formulated by the manufacturer to support hair, skin, nails, bones and joints","so":"Shirkaddu waxay u samaysay taageerada timaha, maqaarka, ciddiyaha, lafaha iyo kalagoysyada"},{"en":"Powder format — easy to mix into your daily drink","so":"Qaab budo ah — si fudud ayaa loogu qasi karaa cabitaankaaga maalinlaha ah"}]'::jsonb, null, null, null, null, array['collagen-peptides.webp']::text[], true, false, 52),
  ('turmeric-curcumin', 'Turmeric Curcumin', 'Huruud Curcumin', 'NOW', array['Turmeric', 'Curcumin', 'Huruud']::text[], (select id from public.categories where slug = 'supplements'), null, 'Standardised extract · 95% curcuminoids · 60 veg capsules', 'NOW Turmeric Curcumin — a standardised turmeric extract with 95% curcuminoids in vegetarian capsules.', 'NOW Turmeric Curcumin — soosaar huruud ah oo la habeeyay, leh 95% curcuminoids, ku jira kaabsuul khudradeed.', '[{"en":"Standardised extract with 95% curcuminoids, as labelled","so":"Soosaar la habeeyay oo leh 95% curcuminoids, sida ku qoran calaamadda"},{"en":"Turmeric has a long history of use in traditional Ayurvedic practice","so":"Huruudku wuxuu leeyahay taariikh dheer oo isticmaal ah dhaqanka Ayurveda"},{"en":"Vegetarian / vegan capsules","so":"Kaabsuul khudradeed / vegan ah"}]'::jsonb, null, null, null, null, array['turmeric-curcumin.webp']::text[], true, false, 53),
  ('omega-3-fish-oil-2000', 'Omega 3 Fish Oil 2000 mg', null, 'New Leaf', array['Omega 3', 'Fish oil']::text[], (select id from public.categories where slug = 'supplements'), null, '2,000 mg per serving · EPA & DHA · 180 softgels', 'New Leaf high-strength Omega 3 fish oil — 2,000 mg per serving, rich in EPA and DHA, in a large 180-softgel bottle.', 'New Leaf Omega 3 fish oil oo xoog badan — 2,000 mg qaadasho kasta, hodan ku ah EPA iyo DHA, ku jira dhalo weyn oo 180 kaabsuul jilicsan ah.', '[{"en":"EPA and DHA contribute to the normal function of the heart","so":"EPA iyo DHA waxay gacan ka geystaan shaqada caadiga ah ee wadnaha"},{"en":"DHA contributes to the maintenance of normal brain function","so":"DHA wuxuu gacan ka geystaa ilaalinta shaqada caadiga ah ee maskaxda"},{"en":"High strength: 2,000 mg fish oil per serving, as labelled","so":"Xoog badan: 2,000 mg fish oil qaadasho kasta, sida ku qoran calaamadda"}]'::jsonb, null, null, null, null, array['omega-3-fish-oil.webp']::text[], true, false, 54),
  ('coq10-200', 'CoQ10 200 mg', null, 'NOW', array['Coenzyme Q10', 'CoQ10']::text[], (select id from public.categories where slug = 'supplements'), null, '200 mg · 60 veg capsules', 'NOW CoQ10 200 mg — coenzyme Q10 in vegetarian capsules, formulated for cardiovascular health and cellular energy, as labelled.', 'NOW CoQ10 200 mg — coenzyme Q10 ku jira kaabsuul khudradeed, loogu talagalay caafimaadka wadnaha iyo tamarta unugyada, sida ku qoran calaamadda.', '[{"en":"Coenzyme Q10 plays a role in the body''s cellular energy production","so":"Coenzyme Q10 wuxuu door ku leeyahay soo saarista tamarta unugyada jirka"},{"en":"Formulated for cardiovascular health support, as labelled by the manufacturer","so":"Loogu talagalay taageerada caafimaadka wadnaha iyo xididdada, sida ay shirkaddu ku qortay calaamadda"},{"en":"Vegetarian / vegan capsules","so":"Kaabsuul khudradeed / vegan ah"}]'::jsonb, null, null, null, null, array['coq10.webp']::text[], true, false, 55),
  ('l-arginine', 'L-Arginine', null, 'NOW', array['Arginine', 'L-Arginane']::text[], (select id from public.categories where slug = 'supplements'), null, '500 mg capsules or 1,000 mg double-strength tablets', 'NOW L-Arginine, a conditionally essential amino acid — available as 500 mg vegetarian capsules or double-strength 1,000 mg tablets.', 'NOW L-Arginine, oo ah amino acid muhiim noqda xaaladaha qaarkood — waxaa la helaa kaabsuul khudradeed oo 500 mg ah ama kiniin laba-jibbaar ah oo 1,000 mg ah.', '[{"en":"A conditionally essential amino acid","so":"Amino acid muhiim noqda xaaladaha qaarkood"},{"en":"A precursor of nitric oxide in the body, as labelled","so":"Waa walaxda jirku ka sameeyo nitric oxide, sida ku qoran calaamadda"},{"en":"Choose 500 mg capsules or double-strength 1,000 mg tablets","so":"Dooro kaabsuul 500 mg ah ama kiniin laba-jibbaar ah oo 1,000 mg ah"}]'::jsonb, null, null, '[{"en":"500 mg · 100 veg capsules","so":"500 mg · 100 kaabsuul khudradeed"},{"en":"Double Strength 1,000 mg · 120 tablets","so":"Laba-jibbaar 1,000 mg · 120 kiniin"}]'::jsonb, null, array['l-arginine-500.webp', 'l-arginine-1000.webp']::text[], true, false, 56),
  ('l-carnitine-1000', 'L-Carnitine 1000 mg', null, 'NOW', array['Carnitine', 'Carnipure']::text[], (select id from public.categories where slug = 'supplements'), null, '1,000 mg · 50 tablets', 'NOW L-Carnitine 1,000 mg in its purest, clinically tested form, as labelled — formulated for fitness support.', 'NOW L-Carnitine 1,000 mg oo ah qaabkiisa ugu saafisan oo si caafimaad ah loo tijaabiyay, sida ku qoran calaamadda — loogu talagalay taageerada jir-dhiska.', '[{"en":"Involved in transporting fatty acids into cells for energy, as labelled","so":"Wuxuu door ku leeyahay u qaadista asiidhyada dufanka unugyada si tamar looga helo, sida ku qoran calaamadda"},{"en":"Pure, clinically tested form, as stated by the manufacturer","so":"Qaab saafi ah oo si caafimaad ah loo tijaabiyay, sida ay shirkaddu sheegtay"},{"en":"Formulated for fitness support, as labelled","so":"Loogu talagalay taageerada jir-dhiska, sida ku qoran calaamadda"}]'::jsonb, null, null, null, null, array['l-carnitine.webp']::text[], true, false, 57),
  ('liquid-chlorophyll', 'Liquid Chlorophyll', null, 'NOW', array['Chlorophyll', 'Chlorphyll']::text[], (select id from public.categories where slug = 'supplements'), null, '100 mg per teaspoon · 473 ml (16 fl oz)', 'NOW Liquid Chlorophyll — 100 mg per teaspoon of the natural green plant pigment, described by the manufacturer as an internal deodoriser.', 'NOW Liquid Chlorophyll — 100 mg qaaddo yar kasta oo ah midabka cagaarka ee dabiiciga ah ee dhirta, shirkadduna waxay ku tilmaantay mid gudaha ka udgoonsiiya.', '[{"en":"Chlorophyll is the natural green pigment found in plants","so":"Chlorophyll waa midabka cagaarka ah ee dabiiciga ah ee laga helo dhirta"},{"en":"Described by the manufacturer as an internal deodoriser that helps freshen breath","so":"Shirkaddu waxay ku tilmaantay mid gudaha ka udgoonsiiya oo gacan ka geysta udgoonaanta afka"},{"en":"Liquid format — 100 mg per teaspoon, mixed into water or juice","so":"Qaab dareere ah — 100 mg qaaddo yar kasta, lagu qaso biyo ama casiir"}]'::jsonb, null, null, null, null, array['liquid-chlorophyll.webp']::text[], true, false, 58),
  ('l-glutamine-500', 'L-Glutamine 500 mg', null, 'NOW', array['Glutamine']::text[], (select id from public.categories where slug = 'supplements'), null, '500 mg · 120 veg capsules', 'NOW L-Glutamine 500 mg — the body''s most abundant free amino acid, in vegetarian capsules.', 'NOW L-Glutamine 500 mg — amino acid-ka xorta ah ee jirka ugu badan, ku jira kaabsuul khudradeed.', '[{"en":"L-glutamine is the most abundant free amino acid in the body","so":"L-glutamine waa amino acid-ka xorta ah ee jirka ugu badan"},{"en":"Acts as a nitrogen transporter in protein metabolism, as labelled","so":"Wuxuu u shaqeeyaa gaadiid nitrogen ah dheef-shiidka borotiinka, sida ku qoran calaamadda"},{"en":"Vegetarian / vegan capsules","so":"Kaabsuul khudradeed / vegan ah"}]'::jsonb, null, null, null, null, array['l-glutamine.webp']::text[], true, false, 59),
  ('calcium-vitamin-d', 'Calcium with Vitamin D', null, 'Nutricost', array['Calcium', 'Calcium D3']::text[], (select id from public.categories where slug = 'supplements'), null, '1,200 mg calcium · 50 mcg vitamin D · 240 tablets', 'Nutricost Calcium with Vitamin D — 1,200 mg calcium and 50 mcg (2,000 IU) vitamin D per serving, in a large 240-tablet bottle.', 'Nutricost Calcium with Vitamin D — 1,200 mg kaalshiyam iyo 50 mcg (2,000 IU) fitamiin D qaadasho kasta, ku jira dhalo weyn oo 240 kiniin ah.', '[{"en":"Calcium is needed for the maintenance of normal bones","so":"Kaalshiyamku waxaa loo baahan yahay ilaalinta lafo caadi ah"},{"en":"Vitamin D contributes to normal absorption and use of calcium","so":"Fitamiin D wuxuu gacan ka geystaa nuugista iyo isticmaalka caadiga ah ee kaalshiyamka"},{"en":"1,200 mg calcium with 50 mcg (2,000 IU) vitamin D per serving, as labelled","so":"1,200 mg kaalshiyam iyo 50 mcg (2,000 IU) fitamiin D qaadasho kasta, sida ku qoran calaamadda"}]'::jsonb, null, '{"en":"Do not exceed the stated dose. Ask a healthcare professional if you take other calcium or vitamin D supplements.","so":"Ha dhaafin qiyaasta lagu qoray. Weydii xirfadle caafimaad haddii aad qaadato kaabayaal kale oo kaalshiyam ama fitamiin D ah."}'::jsonb, null, null, array['calcium-vitamin-d.webp']::text[], true, false, 60),
  ('cell-tech', 'Cell-Tech Creatine', null, 'MuscleTech', array['Cell Tech']::text[], (select id from public.categories where slug = 'sports'), 'nutrition', 'Fruit punch · 2.27 kg', 'MuscleTech''s creatine formula with carbohydrates, made for strength-focused training.', 'Isku-darka creatine ee MuscleTech oo lagu daray karbohaydraydh, loogu talagalay tababarka xoogga.', '[{"en":"Creatine increases physical performance in successive bursts of short-term, high-intensity exercise","so":"Creatine-ku wuxuu kordhiyaa waxqabadka jirka marka si isdaba-joog ah loo sameeyo jimicsi gaaban oo xooggan"},{"en":"Combines creatine with carbohydrates for use after training","so":"Wuxuu isku daraa creatine iyo karbohaydraydh si loo isticmaalo kadib tababarka"},{"en":"Fruit punch flavoured powder that mixes easily with water","so":"Budo dhadhan fruit punch leh oo si fudud biyo ugu milma"}]'::jsonb, null, null, null, null, array['cell-tech.webp']::text[], true, false, 61),
  ('creatine-micronized', 'Creatine Monohydrate Micronized', null, 'Applied Nutrition', array['Creatine Micronized']::text[], (select id from public.categories where slug = 'sports'), 'nutrition', '100% creatine monohydrate · unflavoured', '100% micronised creatine monohydrate from Applied Nutrition Professional, tested for athletes.', 'Creatine monohydrate 100% ah oo la jilciyay (micronised) oo ka yimid Applied Nutrition Professional, loona baaray ciyaartoyda.', '[{"en":"Creatine increases physical performance in successive bursts of short-term, high-intensity exercise","so":"Creatine-ku wuxuu kordhiyaa waxqabadka jirka marka si isdaba-joog ah loo sameeyo jimicsi gaaban oo xooggan"},{"en":"Micronised powder for smooth, easy mixing","so":"Budo la jilciyay oo si siman oo fudud u milma"},{"en":"Unflavoured — add to any shake or drink","so":"Dhadhan ma laha — ku dar cabbitaan kasta ama shake"}]'::jsonb, null, null, null, null, array['creatine-micronized.webp']::text[], true, false, 62),
  ('creatine-monohydrate', 'Creatine Monohydrate', null, null, '{}'::text[], (select id from public.categories where slug = 'sports'), 'nutrition', 'Creatine monohydrate powder', 'Classic creatine monohydrate powder — a staple for strength and power training.', 'Budada creatine monohydrate ee caadiga ah — asaas u ah tababarka xoogga iyo awoodda.', '[{"en":"Creatine increases physical performance in successive bursts of short-term, high-intensity exercise","so":"Creatine-ku wuxuu kordhiyaa waxqabadka jirka marka si isdaba-joog ah loo sameeyo jimicsi gaaban oo xooggan"},{"en":"Pure creatine monohydrate powder","so":"Budo creatine monohydrate ah oo saafi ah"},{"en":"Easy to add to water, juice or protein shakes","so":"Si fudud loogu dari karo biyaha, casiirka ama shake-ga borotiinka"}]'::jsonb, null, null, null, null, array['creatine-monohydrate.webp']::text[], true, false, 63),
  ('creatine-monohydrate-icy-blue-razz', 'Creatine Monohydrate — Icy Blue Razz', null, 'Applied Nutrition', array['Creatine Monohydrtae', 'Juicy flavours']::text[], (select id from public.categories where slug = 'sports'), 'nutrition', 'Micronised · Icy Blue Razz · 50 servings', 'Micronised creatine monohydrate with a juicy Icy Blue Razz flavour, from Applied Nutrition.', 'Creatine monohydrate la jilciyay oo leh dhadhanka macaan ee Icy Blue Razz, kana yimid Applied Nutrition.', '[{"en":"Creatine increases physical performance in successive bursts of short-term, high-intensity exercise","so":"Creatine-ku wuxuu kordhiyaa waxqabadka jirka marka si isdaba-joog ah loo sameeyo jimicsi gaaban oo xooggan"},{"en":"Juicy Icy Blue Razz flavour — 50 servings","so":"Dhadhan macaan oo Icy Blue Razz ah — 50 qaadasho"},{"en":"Tested for athletes and approved by the Vegetarian Society","so":"Loo baaray ciyaartoyda, waxaana ansixiyay Vegetarian Society"}]'::jsonb, null, null, null, null, array['creatine-monohydrate-icy-blue.webp']::text[], true, false, 64),
  ('iso100-dunkin-glazed-donut', 'ISO100 Dunkin'' Glazed Donut Protein', null, 'Dymatize', array['Dunkin', 'Protein tub', 'Whey']::text[], (select id from public.categories where slug = 'sports'), 'nutrition', '25 g protein · 5.5 g BCAAs · 910 g · 20 servings', 'Dymatize ISO100 hydrolysed whey protein isolate in Dunkin'' Glazed Donut flavour.', 'Dymatize ISO100 — borotiin whey isolate ah oo la jajabiyay, leh dhadhanka Dunkin'' Glazed Donut.', '[{"en":"Protein contributes to the growth and maintenance of muscle mass","so":"Borotiinku wuxuu gacan ka geystaa korriinka iyo ilaalinta cufnaanta murqaha"},{"en":"25 g of protein per serving from hydrolysed whey protein isolate","so":"25 g oo borotiin ah qaadasho kasta, oo ka yimid whey protein isolate la jajabiyay"},{"en":"Dessert-style Dunkin'' Glazed Donut flavour","so":"Dhadhan macmacaan u eg oo Dunkin'' Glazed Donut ah"}]'::jsonb, null, null, null, null, array['iso100-dunkin.webp']::text[], true, true, 65),
  ('gold-creatine', 'Gold Creatine', null, 'Kevin Levrone', '{}'::text[], (select id from public.categories where slug = 'sports'), 'nutrition', '300 g · unflavoured', 'Unflavoured creatine powder from the Kevin Levrone Signature Series Gold Line.', 'Budo creatine ah oo aan dhadhan lahayn oo ka tirsan Kevin Levrone Signature Series Gold Line.', '[{"en":"Creatine increases physical performance in successive bursts of short-term, high-intensity exercise","so":"Creatine-ku wuxuu kordhiyaa waxqabadka jirka marka si isdaba-joog ah loo sameeyo jimicsi gaaban oo xooggan"},{"en":"Unflavoured powder for mixing and stacking","so":"Budo aan dhadhan lahayn oo lagu qasi karo kaabayaal kale"},{"en":"Part of the Kevin Levrone Signature Series","so":"Qayb ka mid ah Kevin Levrone Signature Series"}]'::jsonb, null, null, null, null, array['gold-creatine.webp']::text[], true, false, 66),
  ('l-citrulline', 'L-Citrulline 750 mg', null, 'NOW', array['L- Citruline']::text[], (select id from public.categories where slug = 'sports'), 'nutrition', '750 mg · 90 veg capsules', 'Free-form L-citrulline in 750 mg vegetarian capsules — a popular amino acid in sports nutrition.', 'L-citrulline xor ah oo ku jira kaabsuul khudradeed oo 750 mg ah — amino acid caan ka ah nafaqada isboortiga.', '[{"en":"Free-form L-citrulline, a naturally occurring amino acid","so":"L-citrulline xor ah, oo ah amino acid dabiici ahaan jira"},{"en":"Involved in the body''s urea cycle and protein metabolism, as labelled","so":"Wuxuu door ku leeyahay wareegga urea iyo dheef-shiidka borotiinka, sida ku qoran calaamadda"},{"en":"Vegetarian / vegan capsules","so":"Kaabsuul khudradeed / vegan ah"}]'::jsonb, null, null, null, null, array['l-citrulline.webp']::text[], true, false, 67),
  ('lean-mass-gainer', 'Critical Mass Lean Mass Gainer', null, 'Applied Nutrition', array['Lean Mass Gainer', 'Mass gainer']::text[], (select id from public.categories where slug = 'sports'), 'nutrition', '6 kg · chocolate · Professional & Original', 'Applied Nutrition Critical Mass in chocolate flavour — available as the Professional lean mass gainer or the Original high-calorie gainer.', 'Applied Nutrition Critical Mass oo dhadhan shukulaato leh — waxaa la helaa nooca Professional (lean mass gainer) ama Original (high-calorie gainer).', '[{"en":"Protein contributes to the growth and maintenance of muscle mass","so":"Borotiinku wuxuu gacan ka geystaa korriinka iyo ilaalinta cufnaanta murqaha"},{"en":"Professional: 42 g protein and 566 kcal per serving, as labelled","so":"Professional: 42 g borotiin iyo 566 kcal qaadasho kasta, sida ku qoran calaamadda"},{"en":"Helps meet higher calorie needs for those aiming to gain weight","so":"Wuxuu kaa caawiyaa buuxinta baahida kaloori ee sare haddii aad doonayso inaad miisaan kordhiso"}]'::jsonb, null, null, '[{"en":"Professional · Lean Mass Gainer","so":"Professional · Lean Mass Gainer"},{"en":"Professional · Lean Mass Gainer","so":"Professional · Lean Mass Gainer"},{"en":"Original · High Calorie Gainer","so":"Original · High Calorie Gainer"}]'::jsonb, null, array['lean-mass-gainer.webp', 'lean-mass-gainer-2.webp', 'lean-mass-gainer-3.webp']::text[], true, true, 68),
  ('mass-tech-extreme-2000', 'Mass-Tech Extreme 2000', null, 'MuscleTech', array['Mass Tech']::text[], (select id from public.categories where slug = 'sports'), 'nutrition', 'Vanilla milkshake & triple chocolate brownie · 2.72 kg · 80 g protein', 'MuscleTech''s high-protein mass gainer in vanilla milkshake and triple chocolate brownie flavours, with creatine and added vitamins & minerals.', 'Miisaan-kordhiyaha borotiinka badan ee MuscleTech oo dhadhan vanilla milkshake iyo triple chocolate brownie leh, lagu daray creatine, fitamiinno iyo macdano.', '[{"en":"Protein contributes to the growth and maintenance of muscle mass","so":"Borotiinku wuxuu gacan ka geystaa korriinka iyo ilaalinta cufnaanta murqaha"},{"en":"High-calorie formula (2,350 kcal per serving, as labelled) for those aiming to gain weight","so":"Isku-dar kaloori badan (2,350 kcal qaadasho kasta, sida ku qoran) oo loogu talagalay kuwa doonaya inay miisaan kordhiyaan"},{"en":"Includes 5 g creatine and 20 vitamins & minerals","so":"Waxaa ku jira 5 g creatine iyo 20 fitamiin & macdan"}]'::jsonb, null, null, '[{"en":"Vanilla Milkshake · 2.72 kg bag","so":"Vanilla Milkshake · bac 2.72 kg ah"},{"en":"Triple Chocolate Brownie · 2.72 kg tub","so":"Triple Chocolate Brownie · weel 2.72 kg ah"},{"en":"Triple Chocolate Brownie · 2.72 kg bag (new packaging)","so":"Triple Chocolate Brownie · bac 2.72 kg ah (baakad cusub)"}]'::jsonb, null, array['mass-tech.webp', 'mass-tech-extreme-2000-tub.webp', 'mass-tech-extreme-bag.webp']::text[], true, false, 69),
  ('c4-original-pre-workout', 'C4 Original Pre-Workout', null, 'Cellucor', array['Neon Lime C4', 'C4', 'Pre-workout', 'Icy Blue Raspberry']::text[], (select id from public.categories where slug = 'sports'), 'nutrition', 'Icy Blue Raspberry · 30 servings · 282 g', 'C4 Original, one of the world''s best-known pre-workouts, in Icy Blue Raspberry flavour.', 'C4 Original, mid ka mid ah pre-workout-yada ugu caansan adduunka, oo dhadhan Icy Blue Raspberry leh.', '[{"en":"Contains caffeine, which helps increase alertness","so":"Waxaa ku jira kafeyn, taas oo gacan ka geysata kordhinta feejignaanta"},{"en":"Includes beta-alanine, a popular amino acid in sports nutrition","so":"Waxaa ku jira beta-alanine, amino acid caan ka ah nafaqada isboortiga"},{"en":"Icy Blue Raspberry flavour — 30 servings per tub","so":"Dhadhan Icy Blue Raspberry ah — 30 qaadasho weelkiiba"}]'::jsonb, null, '{"en":"Contains caffeine. Not recommended for children, pregnant or breastfeeding women, or people sensitive to caffeine.","so":"Waxaa ku jira kafeyn. Laguma talinayo carruurta, haweenka uurka leh ama naas-nuujinaya, ama dadka kafeynta u nugul."}'::jsonb, null, null, array['c4-original.webp']::text[], true, true, 70),
