  ('daryeel-shaker-bottle', 'Daryeel Stainless Steel Shaker Bottle', 'Dhalada Qasidda ee Daryeel (Shaker)', 'Daryeel Wellness', array['Shaker', 'Gym bottle', 'Protein shaker']::text[], (select id from public.categories where slug = 'sports'), 'accessories', 'Stainless steel · with whisk ball', 'Daryeel Wellness branded stainless-steel shaker bottle with a wire whisk ball — for smooth protein shakes at home or the gym.', 'Dhalo qasid ah oo bir-ma-dhaxale ah oo summadda Daryeel Wellness leh, ay la socoto kubad qasid — loogu talagalay cabitaannada borotiinka ee siman, guriga ama jimicsiga.', '[{"en":"Durable stainless-steel body","so":"Jir adag oo bir-ma-dhaxale ah"},{"en":"Wire whisk ball for smooth, lump-free shakes","so":"Kubad qasid ah oo cabitaanka ka dhigta mid siman oo aan buro lahayn"},{"en":"Screw-on lid with a flip-top spout","so":"Dabool la xidho oo leh af la furo"}]'::jsonb, null, null, null, null, array['shaker-bottle.webp']::text[], true, false, 80),
  ('gym-gloves', 'Gym Gloves with Wrist Support', 'Gacmo-gashi Jimicsi oo leh Taageero Curcurka', null, array['Gym gloves', 'Workout gloves', 'Lifting gloves']::text[], (select id from public.categories where slug = 'sports'), 'accessories', 'Half-finger · wrist wrap', 'Half-finger workout gloves with padded palms and built-in wrist wraps, for a secure grip during weight training.', 'Gacmo-gashi jimicsi oo faraha badh u furan, leh calaacal suuf leh iyo duub curcur oo ku dhex jira, loogu talagalay qabsasho adag xilliga culayska-qaadista.', '[{"en":"Padded palms for a firmer, more comfortable grip","so":"Calaacal suuf leh oo qabsasho adag oo raaxo leh siisa"},{"en":"Built-in wrist wraps for extra support","so":"Duub curcur oo ku dhex jira oo taageero dheeraad ah siiya"},{"en":"Half-finger design keeps hands cool and flexible","so":"Naqshad faraha badh u furan oo gacmaha qabow iyo dabacsanaan ku haysa"}]'::jsonb, null, null, null, null, array['gym-gloves.webp']::text[], true, false, 81),
  ('knee-sleeves', '7mm Knee Sleeves', 'Jilib-gashi 7mm', 'Aurum Athletics', array['Knee sleeves', 'Knee support']::text[], (select id from public.categories where slug = 'sports'), 'accessories', '7 mm neoprene · pair', 'Aurum Athletics 7 mm neoprene knee sleeves — warmth, compression and support for squats and heavy lifts.', 'Jilib-gashiga neoprene-ka ee 7 mm ee Aurum Athletics — diirimaad, cadaadis iyo taageero loogu talagalay fadhi-kacda (squat) iyo culayska waaweyn.', '[{"en":"7 mm neoprene for warmth and compression","so":"Neoprene 7 mm ah oo diirimaad iyo cadaadis bixiya"},{"en":"Support for the knees during squats and heavy lifts","so":"Taageero jilibka xilliga fadhi-kacda iyo culayska waaweyn"},{"en":"Supplied as a pair","so":"Waxaa la bixiyaa laba (lammaane)"}]'::jsonb, null, null, null, null, array['knee-sleeves.webp']::text[], true, false, 82),
  ('lifting-straps', 'Premium Lifting Straps', 'Suunka Culayska-qaadista', 'Hardbody', array['Lifting straps', 'Wrist straps']::text[], (select id from public.categories where slug = 'sports'), 'accessories', 'Padded · pair', 'Hardbody premium lifting straps — padded wrist straps that help you hold heavy bars for rows, deadlifts and pull-downs.', 'Suunka culayska-qaadista ee Hardbody — suun curcur oo suuf leh oo kaa caawiya inaad qabato birta culus xilliga rows, deadlifts iyo pull-downs.', '[{"en":"Help maintain your grip on heavy pulls and deadlifts","so":"Waxay kaa caawiyaan ilaalinta qabsashadaada xilliga jiidista culus iyo deadlifts"},{"en":"Padded wrist section for comfort","so":"Qayb curcur oo suuf leh oo raaxo leh"},{"en":"Durable stitched construction","so":"Dhismo adag oo si fiican loo tolay"}]'::jsonb, null, null, null, null, array['lifting-straps.webp']::text[], true, false, 83),
  ('gym-duffel-bag', 'Gym Duffel Bag', 'Boorsada Jimicsiga', 'Arrowmax', array['Gym bag', 'Sports bag', 'Duffel']::text[], (select id from public.categories where slug = 'sports'), 'accessories', 'Black', 'Arrowmax black gym duffel bag with a roomy main compartment and sturdy carry handles — for the gym or short trips.', 'Boorsada jimicsiga ee madow ee Arrowmax oo leh qayb weyn oo ballaaran iyo gacan-qabsi adag — loogu talagalay jimicsiga ama safarrada gaagaaban.', '[{"en":"Spacious main compartment for clothes, shoes and accessories","so":"Qayb weyn oo ballaaran oo loogu talagalay dharka, kabaha iyo agabka"},{"en":"Sturdy carry handles","so":"Gacan-qabsi adag"},{"en":"Classic black design for the gym or travel","so":"Naqshad madow oo caadi ah oo ku habboon jimicsiga ama safarka"}]'::jsonb, null, null, null, null, array['gym-duffel-bag.webp']::text[], true, false, 84),
